3. Add 'Export report' button to the analytics page:
  - Create src/features/pulse/analytics/components/ExportReportButton.tsx (client component):
```typescript
'use client';
import { useState } from 'react';
import { Button } from '@/components/ui/Button';
export function ExportReportButton() {
  const [loading, setLoading] = useState(false);
  async function doExport() {
    setLoading(true);
    try {
      const res = await fetch('/api/pulse/reports/culture-export?format=json');
      const data = await res.json();
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `culture-report-${new Date().toISOString().slice(0,10)}.json`;
      a.click();
      URL.revokeObjectURL(url);
    } finally {
      setLoading(false);
    }
  }
  return <Button variant='secondary' icon='solar:download-minimalistic-broken' loading={loading} onClick={doExport}>Export report</Button>;
}
```
  - Import and render ExportReportButton in RecognitionAnalyticsPage.tsx — add it to SetPageHeader's actions prop or as a button next to the page header. Since SetPageHeader accepts `actions: { label, icon, href, variant }[]` and this is a client component with custom onClick, render it in a flex div below SetPageHeader instead:
```typescript
<div className='flex justify-end'><ExportReportButton /></div>
